    54	  });
    55	}
    56	
    57	module.exports = { createApp };
=============== src/http/router.js ===============
     1	'use strict';
     2	
     3	const { AppError, notFound } = require('../lib/errors');
     4	const { sendJson, sendText, readJson } = require('./respond');
     5	
     6	const STATUS_BY_CODE = {
     7	  invalid: 400,
     8	  unauthorized: 401,
     9	  forbidden: 403,
    10	  not_found: 404,
    11	  conflict: 409,
    12	};
    13	
    14	const BODY_METHODS = new Set(['POST', 'PUT', 'PATCH']);
    15	
    16	function matchPath(parts, segments) {
    17	  if (parts.length !== segments.length) return null;
    18	  const params = {};
    19	  for (let i = 0; i < parts.length; i += 1) {
    20	    if (parts[i].startsWith(':')) {
    21	      params[parts[i].slice(1)] = decodeURIComponent(segments[i]);
    22	    } else if (parts[i] !== segments[i]) {
    23	      return null;
    24	    }
    25	  }
    26	  return params;
    27	}
    28	
    29	function createRouter() {
    30	  const routes = [];
    31	
    32	  function add(method, pattern, handler) {
    33	    routes.push({ method, parts: pattern.split('/').filter(Boolean), handler });
    34	  }
    35	
    36	  async function dispatch(req, res) {
    37	    const url = new URL(req.url, 'http://localhost');
    38	    const segments = url.pathname.split('/').filter(Boolean);
    39	    let pathMatched = false;
    40	    for (const route of routes) {
    41	      const params = matchPath(route.parts, segments);
    42	      if (!params) continue;
    43	      pathMatched = true;
    44	      if (route.method !== req.method) continue;
    45	      const body = BODY_METHODS.has(req.method) ? await readJson(req) : {};
    46	      const query = Object.fromEntries(url.searchParams);
    47	      const result = await route.handler({ req, params, query, body });
    48	      if (result.text !== undefined) return sendText(res, result.status, result.text, result.contentType);
    49	      return sendJson(res, result.status, result.body);
    50	    }
    51	    if (pathMatched) return sendJson(res, 405, { error: 'method not allowed' });
    52	    throw notFound('route not found');
    53	  }
    54	
    55	  async function handle(req, res) {
    56	    try {
    57	      await dispatch(req, res);
    58	    } catch (error) {
    59	      if (error instanceof URIError) return sendJson(res, 400, { error: 'malformed path' });
    60	      if (error instanceof AppError) return sendJson(res, STATUS_BY_CODE[error.code] || 400, { error: error.message });
    61	      return sendJson(res, 500, { error: 'internal error' });
    62	    }
    63	  }
    64	
    65	  return { add, handle };
    66	}
    67	
    68	module.exports = { createRouter };
=============== src/http/respond.js ===============
     1	'use strict';
     2	
     3	const { invalid } = require('../lib/errors');
     4	
     5	const MAX_BODY_BYTES = 1024 * 1024;
     6	
     7	function sendJson(res, status, body) {
     8	  const payload = body === undefined ? '' : JSON.stringify(body);
     9	  res.writeHead(status, {
    10	    'content-type': 'application/json; charset=utf-8',
    11	    'content-length': Buffer.byteLength(payload),
    12	  });
    13	  res.end(payload);
    14	}
    15	
    16	function sendText(res, status, text, contentType = 'text/plain; charset=utf-8') {
    17	  res.writeHead(status, { 'content-type': contentType, 'content-length': Buffer.byteLength(text) });
    18	  res.end(text);
    19	}
    20	
    21	function readJson(req) {
    22	  return new Promise((resolve, reject) => {
    23	    const chunks = [];
    24	    let size = 0;
    25	    req.on('data', (chunk) => {
    26	      size += chunk.length;
    27	      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    28	    });
    29	    req.on('end', () => {
    30	      if (size > MAX_BODY_BYTES) return reject(invalid('request body too large'));
    31	      if (size === 0) return resolve({});
    32	      let value;
    33	      try {
    34	        value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    35	      } catch {
    36	        return reject(invalid('request body must be valid JSON'));
    37	      }
    38	      if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    39	        return reject(invalid('request body must be a JSON object'));
    40	      }
    41	      return resolve(value);
    42	    });
    43	    req.on('error', reject);
    44	  });
    45	}
    46	
    47	function parseCookies(header = '') {
    48	  const cookies = {};
    49	  for (const part of header.split(';')) {
    50	    const index = part.indexOf('=');
    51	    if (index < 1) continue;
    52	    cookies[part.slice(0, index).trim()] = decodeURIComponent(part.slice(index + 1).trim());
    53	  }
    54	  return cookies;
    55	}
    56	
    57	module.exports = { sendJson, sendText, readJson, parseCookies };
=============== src/auth/guard.js ===============
     1	'use strict';
     2	
     3	const { unauthorized, forbidden } = require('../lib/errors');
     4	
     5	function createGuard({ tokens, users }) {
     6	  function authenticate(req) {
     7	    const [scheme, token] = (req.headers.authorization || '').split(' ');
     8	    if (scheme !== 'Bearer' || !token) return null;
     9	    const claims = tokens.verify(token);
    10	    return claims ? users.find(claims.sub) : null;
    11	  }
    12	
    13	  function requireUser(handler) {
    14	    return async (ctx) => {
    15	      const user = authenticate(ctx.req);
    16	      if (!user) throw unauthorized();
    17	      return handler({ ...ctx, user });
    18	    };
    19	  }
    20	
    21	  function requireAdmin(handler) {
    22	    return requireUser(async (ctx) => {
    23	      if (ctx.user.role !== 'admin') throw forbidden('admin role required');
    24	      return handler(ctx);
    25	    });
    26	  }
    27	
    28	  return { requireUser, requireAdmin };
    29	}
    30	
    31	module.exports = { createGuard };
=============== src/auth/tokens.js ===============
     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	
     5	function createTokenService({ secret, ttlSeconds }) {
     6	  if (!secret) throw new Error('a token secret is required');
     7	
     8	  function sign(payload) {
     9	    return crypto.createHmac('sha256', secret).update(payload).digest('base64url');
    10	  }
    11	
    12	  function issue(claims) {
    13	    const exp = Math.floor(Date.now() / 1000) + ttlSeconds;
    14	    const payload = Buffer.from(JSON.stringify({ ...claims, exp })).toString('base64url');
    15	    return `${payload}.${sign(payload)}`;
    16	  }
    17	
    18	  function verify(token) {
    19	    const [payload, signature, extra] = String(token).split('.');
    20	    if (!payload || !signature || extra !== undefined) return null;
    21	    if (signature !== sign(payload)) return null;
    22	    let claims;
    23	    try {
    24	      claims = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    25	    } catch {
    26	      return null;
    27	    }
    28	    if (!claims || typeof claims.exp !== 'number' || claims.exp * 1000 <= Date.now()) return null;
    29	    return claims;
    30	  }
    31	
    32	  return { issue, verify };
    33	}
    34	
    35	module.exports = { createTokenService };
