     1	'use strict';
     2	
     3	class AppError extends Error {
     4	  constructor(code, message) {
     5	    super(message);
     6	    this.name = 'AppError';
     7	    this.code = code;
     8	  }
     9	}
    10	
    11	const invalid = (message) => new AppError('invalid', message);
    12	const unauthorized = (message = 'authentication required') => new AppError('unauthorized', message);
    13	const forbidden = (message = 'not allowed') => new AppError('forbidden', message);
    14	const notFound = (message = 'not found') => new AppError('not_found', message);
    15	const conflict = (message) => new AppError('conflict', message);
    16	
    17	module.exports = { AppError, invalid, unauthorized, forbidden, notFound, conflict };
