     3	const DEFAULT_PAGE_SIZE = 20;
     4	const MAX_PAGE_SIZE = 100;
     5	
     6	function toPositiveInt(value, fallback) {
     7	  const number = Number.parseInt(value, 10);
     8	  return Number.isInteger(number) && number > 0 ? number : fallback;
     9	}
    10	
    11	function paginate(items, query = {}) {
    12	  const pageSize = Math.min(toPositiveInt(query.pageSize, DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE);
    13	  const page = toPositiveInt(query.page, 1);
    14	  const start = (page - 1) * pageSize;
    15	  return {
    16	    items: items.slice(start, start + pageSize),
    17	    page,
    18	    pageSize,
    19	    total: items.length,
    20	    totalPages: Math.max(1, Math.floor(items.length / pageSize)),
    21	  };
    22	}
    23	
    24	module.exports = { paginate };

