    18	    if (!isAmount(amount)) throw invalid('amount must be a positive amount with at most two decimals');
    19	    const order = orders.getOwned(user, orderId);
    20	    if (order.status !== 'pending') throw conflict('order is not awaiting payment');
    21	    if (Math.round(amount * 100) !== orderTotalCents(order)) throw invalid('amount does not match the order total');
    22	    const charge = gateway.charge({ amount, reference: order.id });
    23	    const payment = store.insert('payments', {
    24	      orderId: order.id,
    25	      userId: user.id,
    26	      amount,
    27	      status: charge.status,
    28	      providerReference: charge.id,
    29	      createdAt: new Date().toISOString(),
    30	    });
    31	    orders.markPaid(order.id, payment.id);
    32	    return payment;
    33	  }
