'use strict';
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createApp } = require('<run-project>/src/app.js');

const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-reports-'));
fs.writeFileSync(path.join(reportDir, '..', 'SECRET-OUTSIDE.txt'), 'top secret payroll\n');

function mk(port) {
  return function call(method, urlPath, { body, token } = {}) {
    return new Promise((resolve, reject) => {
      const payload = body === undefined ? undefined : JSON.stringify(body);
      const headers = {};
      if (payload !== undefined) headers['content-type'] = 'application/json';
      if (token) headers.authorization = `Bearer ${token}`;
      const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          let parsed; try { parsed = JSON.parse(text); } catch {}
          resolve({ status: res.statusCode, body: parsed, text });
        });
      });
      req.on('error', reject);
      req.end(payload);
    });
  };
}

(async () => {
  const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
  const app = createApp({ secret: 'probe-secret', reportDir, admin: ADMIN });
  const port = await app.listen(0);
  const call = mk(port);
  const login = async (email, password) => (await call('POST', '/sessions', { body: { email, password } })).body.token;
  const signUp = async (email) => { await call('POST', '/users', { body: { email, password: 'correct-horse', name: email } }); return login(email, 'correct-horse'); };

  const adminToken = await login(ADMIN.email, ADMIN.password);
  const alice = await signUp('alice@example.com');
  const bob = await signUp('bob@example.com');

  const order = (await call('POST', '/orders', { token: alice, body: { items: [{ sku: 'X', unitPrice: 10, quantity: 1 }] } })).body;

  // 1. IDOR on GET /orders/:id
  const idor = await call('GET', `/orders/${order.id}`, { token: bob });
  console.log('[1] IDOR GET /orders/:id as non-owner ->', idor.status, JSON.stringify(idor.body && idor.body.userId));

  // 2. cancel after ship (README: shipped can no longer be cancelled)
  await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: 10 } });
  await call('POST', `/orders/${order.id}/ship`, { token: adminToken });
  const lateCancel = await call('POST', `/orders/${order.id}/cancel`, { token: alice });
  console.log('[2] cancel a SHIPPED order ->', lateCancel.status, JSON.stringify(lateCancel.body && lateCancel.body.status));

  // 3. totalPages
  for (let i = 0; i < 24; i += 1) await call('POST', '/orders', { token: bob, body: { items: [{ sku: 'Y', unitPrice: 1, quantity: 1 }] } });
  const paged = await call('GET', '/orders?page=1&pageSize=10', { token: bob });
  console.log('[3] totalPages for', paged.body.total, 'items @ pageSize 10 ->', paged.body.totalPages, '(expected 3)');
  const past = await call('GET', '/orders?page=99&pageSize=10', { token: bob });
  console.log('[3b] page=99 ->', past.status, 'items', past.body.items.length, 'page', past.body.page);

  // 4. float money
  const cents = await call('POST', '/orders', { token: alice, body: { items: [{ sku: 'Z', unitPrice: 0.1, quantity: 3 }] } });
  console.log('[4] total for 0.1 x3 ->', JSON.stringify(cents.body.total), '(expected 0.3)');
  const pay = await call('POST', '/payments', { token: alice, body: { orderId: cents.body.id, amount: 0.3 } });
  console.log('[4b] paying 0.3 for that order ->', pay.status, JSON.stringify(pay.body));

  // 5. path traversal on report download
  const trav = await call('GET', '/reports/..%2FSECRET-OUTSIDE.txt', { token: adminToken });
  console.log('[5] GET /reports/..%2FSECRET-OUTSIDE.txt ->', trav.status, JSON.stringify(trav.text));

  // 6. 405 / unknown route
  console.log('[6] DELETE /users ->', (await call('DELETE', '/users', { token: adminToken })).status);
  console.log('[6b] GET /nope ->', (await call('GET', '/nope')).status);

  // 7. CSV of an order with a weird sku / status field injection? ids are uuids - check report row count
  await app.close();
  fs.rmSync(reportDir, { recursive: true, force: true });
  try { fs.rmSync(path.join(reportDir, '..', 'SECRET-OUTSIDE.txt')); } catch {}
})();
