'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { isAmount, toCents, sumLines } = require('../src/lib/money');

test('a line total is exact to the cent', () => {
  // 0.1 * 3 in binary floating point is 0.30000000000000004.
  assert.equal(sumLines([{ unitPrice: 0.1, quantity: 3 }]), 0.3);
  assert.equal(sumLines([{ unitPrice: 0.07, quantity: 3 }]), 0.21);
  assert.equal(sumLines([{ unitPrice: 1.15, quantity: 3 }]), 3.45);
});

test('an order total is exact across several lines', () => {
  assert.equal(sumLines([
    { unitPrice: 0.1, quantity: 1 },
    { unitPrice: 0.2, quantity: 1 },
  ]), 0.3);
  assert.equal(sumLines([
    { unitPrice: 12.5, quantity: 2 },
    { unitPrice: 5, quantity: 1 },
  ]), 30);
  assert.equal(sumLines([{ unitPrice: 19.99, quantity: 7 }]), 139.93);
});

test('toCents rounds a currency amount to whole cents', () => {
  assert.equal(toCents(0.3), 30);
  assert.equal(toCents(49), 4900);
  assert.equal(toCents(19.99), 1999);
});

test('isAmount accepts positive amounts with at most two decimals', () => {
  for (const value of [0.01, 1, 12.5, 19.99]) assert.equal(isAmount(value), true, `${value}`);
  for (const value of [0, -1, 1.234, NaN, Infinity, '1', null, undefined]) {
    assert.equal(isAmount(value), false, `${value}`);
  }
});
EOF
