'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { paginate } = require('../src/lib/pagination');

const items = (count) => Array.from({ length: count }, (_, index) => index);

test('totalPages counts the pages needed to show every item', () => {
  assert.equal(paginate(items(24), { pageSize: '10' }).totalPages, 3);
  assert.equal(paginate(items(21), { pageSize: '20' }).totalPages, 2);
  assert.equal(paginate(items(20), { pageSize: '20' }).totalPages, 1);
  assert.equal(paginate(items(1), { pageSize: '20' }).totalPages, 1);
});

test('totalPages is at least 1 when there is nothing to show', () => {
  const page = paginate(items(0), {});
  assert.equal(page.totalPages, 1);
  assert.equal(page.total, 0);
  assert.deepEqual(page.items, []);
});

test('the last page is reachable and holds the remainder', () => {
  const last = paginate(items(24), { page: '3', pageSize: '10' });
  assert.equal(last.items.length, 4);
  assert.deepEqual(last.items, [20, 21, 22, 23]);
});

test('page and pageSize fall back to their defaults and respect the maximum', () => {
  assert.equal(paginate(items(5), {}).pageSize, 20);
  assert.equal(paginate(items(5), {}).page, 1);
  assert.equal(paginate(items(5), { pageSize: '0' }).pageSize, 20);
  assert.equal(paginate(items(5), { pageSize: 'abc' }).pageSize, 20);
  assert.equal(paginate(items(500), { pageSize: '1000' }).pageSize, 100);
});
