'use strict';

// Architecture rules as code, in the project's own stack: these are the
// dependency constraints Gate L accepted, enforced without a third-party
// linter so the service keeps its zero-dependency promise.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const SRC = path.join(__dirname, '..', 'src');

// A subsystem is a directory, or a single file for a facade. Order matters:
// the first matching pattern owns the file.
const SUBSYSTEMS = [
  { name: 'root', match: (rel) => rel === 'app.js' },
  { name: 'transport', match: (rel) => rel.startsWith('http/') || rel.endsWith('/routes.js') },
  { name: 'service', match: (rel) => rel.endsWith('/service.js') },
  { name: 'persistence', match: (rel) => rel.startsWith('store/') },
  { name: 'shared', match: (rel) => rel.startsWith('lib/') },
  { name: 'auth', match: (rel) => rel.startsWith('auth/') },
];

const FORBIDDEN = [
  { from: 'transport', to: ['persistence'] },
  { from: 'shared', to: ['root', 'transport', 'service', 'persistence', 'auth'] },
];

function sourceFiles(dir = SRC, prefix = '') {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) return sourceFiles(path.join(dir, entry.name), rel);
    return entry.name.endsWith('.js') ? [rel] : [];
  });
}

function subsystemOf(rel) {
  const found = SUBSYSTEMS.find((subsystem) => subsystem.match(rel));
  return found ? found.name : null;
}

function internalImports(rel) {
  const text = fs.readFileSync(path.join(SRC, rel), 'utf8');
  const targets = [...text.matchAll(/require\('(\.[^']+)'\)/g)].map((m) => m[1]);
  return targets.map((target) => {
    const resolved = path.relative(SRC, path.resolve(path.dirname(path.join(SRC, rel)), target));
    return resolved.split(path.sep).join('/').replace(/\.js$/, '') + '.js';
  });
}

// Directive 8: a file matching no declared subsystem is invisible to every
// rule below, so an undeclared file is itself a failure.
test('every source file belongs to a declared subsystem', () => {
  const undeclared = sourceFiles().filter((rel) => subsystemOf(rel) === null);
  assert.deepEqual(undeclared, [], `undeclared files: ${undeclared.join(', ')}`);
});

test('no subsystem imports across a forbidden edge', () => {
  const violations = [];
  for (const rel of sourceFiles()) {
    const from = subsystemOf(rel);
    const rule = FORBIDDEN.find((candidate) => candidate.from === from);
    if (!rule) continue;
    for (const target of internalImports(rel)) {
      const to = subsystemOf(target);
      if (rule.to.includes(to)) violations.push(`${rel} (${from}) -> ${target} (${to})`);
    }
  }
  assert.deepEqual(violations, [], `forbidden edges: ${violations.join('; ')}`);
});

// Aspect exclusivity: currency-unit conversion has one obligation and one
// mechanism. Gate E rejected this as an import rule (it constrains an
// operation, not an edge), so it is a coverage check instead.
test('only the money module converts between currency units and cents', () => {
  const offenders = sourceFiles()
    .filter((rel) => rel !== 'lib/money.js')
    .filter((rel) => /\*\s*100\b/.test(fs.readFileSync(path.join(SRC, rel), 'utf8')));
  assert.deepEqual(offenders, [], `cent arithmetic outside lib/money.js: ${offenders.join(', ')}`);
});
EOF
