1	'use strict';
2	
3	const crypto = require('node:crypto');
4	
5	function createTokenService({ secret, ttlSeconds }) {
6	  if (!secret) throw new Error('a token secret is required');
7	
8	  function sign(payload) {
9	    return crypto.createHmac('sha256', secret).update(payload).digest('base64url');
10	  }
11	
12	  function signatureMatches(candidate, expected) {
13	    const left = Buffer.from(candidate, 'utf8');
14	    const right = Buffer.from(expected, 'utf8');
15	    return left.length === right.length && crypto.timingSafeEqual(left, right);
16	  }
17	
18	  function issue(claims) {
19	    const exp = Math.floor(Date.now() / 1000) + ttlSeconds;
20	    const payload = Buffer.from(JSON.stringify({ ...claims, exp })).toString('base64url');
21	    return `${payload}.${sign(payload)}`;
22	  }
23	
24	  function verify(token) {
25	    const [payload, signature, extra] = String(token).split('.');
26	    if (!payload || !signature || extra !== undefined) return null;
27	    if (!signatureMatches(signature, sign(payload))) return null;
28	    let claims;
29	    try {
30	      claims = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
31	    } catch {
32	      return null;
33	    }
34	    if (!claims || typeof claims.exp !== 'number' || claims.exp * 1000 <= Date.now()) return null;
35	    return claims;
36	  }
37	
38	  return { issue, verify };
39	}
40	
41	module.exports = { createTokenService };
