13	function createPaymentService({ store, orders, gateway = manualGateway }) {
14	  if (!gateway || typeof gateway.charge !== 'function') {
15	    throw new TypeError('a payment gateway must implement charge()');
16	  }
17	
18	  function capture(user, { orderId, amount }) {
19	    if (typeof orderId !== 'string' || orderId === '') throw invalid('orderId is required');
20	    if (!isAmount(amount)) throw invalid('amount must be a positive amount with at most two decimals');
21	    const order = orders.getOwned(user, orderId);
22	    if (order.status !== 'pending') throw conflict('order is not awaiting payment');
23	    if (toCents(amount) !== toCents(order.total)) throw invalid('amount does not match the order total');
24	    const charge = gateway.charge({ amount, reference: order.id });
25	    const payment = store.insert('payments', {
26	      orderId: order.id,
27	      userId: user.id,
28	      amount,
29	      status: charge.status,
30	      providerReference: charge.id,
31	      createdAt: new Date().toISOString(),
32	    });
33	    orders.markPaid(order.id, payment.id);
34	    return payment;
35	  }
36	
37	  function get(user, id) {
38	    const payment = store.get('payments', id);
39	    if (!payment || (user.role !== 'admin' && payment.userId !== user.id)) throw notFound('payment not found');
