46	  const targets = [...text.matchAll(/require\('(\.[^']+)'\)/g)].map((m) => m[1]);
47	  return targets.map((target) => {
48	    const resolved = path.relative(SRC, path.resolve(path.dirname(path.join(SRC, rel)), target));
