'use strict';
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const REPO = '<run-project>';
const { createApp } = require(REPO + '/src/app.js');

const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'p2-reports-'));
// plant a secret file one level above REPORT_DIR
const outside = path.join(path.dirname(reportDir), 'p2-secret.csv');
fs.writeFileSync(outside, 'TOP-SECRET-OUTSIDE-REPORT-DIR\n');
fs.writeFileSync(path.join(reportDir, 'orders-1111111111-aaaaaa.csv'), 'planted-inside\n');

const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
const app = createApp({ secret: 'test-secret', reportDir, admin: ADMIN });

function raw(method, rawPath, { body, token, headers = {} } = {}) {
  return new Promise((resolve, reject) => {
    const payload = body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body));
    const h = { ...headers };
    if (payload !== undefined) h['content-type'] = 'application/json';
    if (token) h.authorization = `Bearer ${token}`;
    const req = http.request({ host: '127.0.0.1', port: PORT, method, path: rawPath, headers: h, agent: false }, (res) => {
      const c = []; res.on('data', (d) => c.push(d));
      res.on('end', () => resolve({ status: res.statusCode, text: Buffer.concat(c).toString('utf8') }));
    });
    req.on('error', reject); req.end(payload);
  });
}
let PORT;
const results = [];
function chk(name, cond, detail) { results.push({ name, ok: !!cond, detail }); console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}  ${detail || ''}`); }

(async () => {
  PORT = await app.listen(0);
  const login = async (email, password) => JSON.parse((await raw('POST', '/sessions', { body: { email, password } })).text).token;
  const signup = async (email, extra = {}) => {
    const r = await raw('POST', '/users', { body: { email, password: 'correct-horse', name: 'C', ...extra } });
    return { res: r, token: await login(email, 'correct-horse') };
  };
  const adminTok = await login(ADMIN.email, ADMIN.password);
  const a = await signup('a@example.com');
  const b = await signup('b@example.com');

  // privilege escalation at registration
  const esc = await signup('esc@example.com', { role: 'admin' });
  const escMe = await raw('GET', '/users/me', { token: esc.token });
  chk('role cannot be set at registration', !/"role":"admin"/.test(escMe.text), escMe.text);
  chk('escalated user cannot list users', (await raw('GET', '/users', { token: esc.token })).status === 403);

  // A creates + pays an order
  const orderA = JSON.parse((await raw('POST', '/orders', { token: a.token, body: { items: [{ sku: 'x', unitPrice: 10.0, quantity: 2 }] } })).text);
  const payA = JSON.parse((await raw('POST', '/payments', { token: a.token, body: { orderId: orderA.id, amount: 20 } })).text);
  console.log('orderA', JSON.stringify(orderA).slice(0, 120));
  console.log('payA  ', JSON.stringify(payA).slice(0, 160));

  // ===== R-OWN: cross-tenant reads =====
  for (const [label, r] of [
    ['GET /orders/:id by non-owner', await raw('GET', `/orders/${orderA.id}`, { token: b.token })],
    ['POST /orders/:id/cancel by non-owner', await raw('POST', `/orders/${orderA.id}/cancel`, { token: b.token })],
    ['GET /payments/:id by non-owner', await raw('GET', `/payments/${payA.id}`, { token: b.token })],
    ['POST /payments on foreign order', await raw('POST', '/payments', { token: b.token, body: { orderId: orderA.id, amount: 20 } })],
  ]) chk(`${label} -> 404`, r.status === 404, `${r.status} ${r.text}`);

  const listB = JSON.parse((await raw('GET', '/orders', { token: b.token })).text);
  chk('GET /orders by B excludes A orders', listB.total === 0, JSON.stringify(listB));
  const listAdmin = JSON.parse((await raw('GET', '/orders', { token: adminTok })).text);
  chk('admin sees all orders', listAdmin.total >= 1, `total=${listAdmin.total}`);
  chk('admin reads foreign order', (await raw('GET', `/orders/${orderA.id}`, { token: adminTok })).status === 200);
  chk('admin reads foreign payment', (await raw('GET', `/payments/${payA.id}`, { token: adminTok })).status === 200);

  // customer on admin routes -> 403
  for (const [label, r] of [
    ['ship', await raw('POST', `/orders/${orderA.id}/ship`, { token: b.token })],
    ['deliver', await raw('POST', `/orders/${orderA.id}/deliver`, { token: b.token })],
    ['users list', await raw('GET', '/users', { token: b.token })],
    ['report export', await raw('POST', '/reports/orders', { token: b.token })],
    ['report download', await raw('GET', '/reports/orders-1111111111-aaaaaa.csv', { token: b.token })],
