  const rb = await raw('GET', '/users/me', { headers: { authorization: 'Basic abc' } });
  chk('Basic scheme -> 401', rb.status === 401, `${rb.status}`);

  // ===== R-DIR: traversal battery =====
  const names = [
    '../p2-secret.csv', '..%2Fp2-secret.csv', '..%252Fp2-secret.csv', '%2e%2e%2fp2-secret.csv',
    '..\\p2-secret.csv', '..%5Cp2-secret.csv', '%2e%2e%5cp2-secret.csv',
    'orders-1-aaaaaa.csv%00../p2-secret.csv', 'orders-1-aaaaaa.csv/../../p2-secret.csv',
    'C:%5CWindows%5Cwin.ini', '%2FWindows%2Fwin.ini', '%5C%5C127.0.0.1%5CC$%5Cwindows%5Cwin.ini',
    'orders-1-aaaaaa.csv.', 'orders-1-aaaaaa.csv ', 'orders-1-aaaaaa.csv::$DATA',
    'orders%2D1111111111%2Daaaaaa.csv', 'ORDERS-1111111111-AAAAAA.CSV',
    'orders-1111111111-aaaaaa.csv%0A', 'orders-1111111111-aaaaaa.csv%0d%0a',
    'orders-\uFF11-aaaaaa.csv', 'orders-１111111111-aaaaaa.csv',
    'orders-1111111111-aaaaaa.csv?x=1',
    '.', '..', '%2e', '%2e%2e',
  ];
  for (const n of names) {
