const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'p2-reports-'));
const outside = path.join(path.dirname(reportDir), 'p2-secret.csv');
fs.writeFileSync(outside, 'TOP-SECRET-OUTSIDE-REPORT-DIR\n');
fs.writeFileSync(path.join(reportDir, 'orders-1111111111-aaaaaa.csv'), 'planted-inside\n');

const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
const app = createApp({ secret: 'test-secret', reportDir, admin: ADMIN });

let PORT;
function raw(method, rawPath, opts) {
  const o = opts || {};
  return new Promise((resolve, reject) => {
    const payload = o.body === undefined ? undefined : (typeof o.body === 'string' ? o.body : JSON.stringify(o.body));
    const h = Object.assign({}, o.headers || {});
    if (payload !== undefined) h['content-type'] = 'application/json';
    if (o.token) h.authorization = 'Bearer ' + o.token;
    const req = http.request({ host: '127.0.0.1', port: PORT, method, path: rawPath, headers: h, agent: false }, (res) => {
      const c = [];
      res.on('data', (d) => c.push(d));
      res.on('end', () => resolve({ status: res.statusCode, text: Buffer.concat(c).toString('utf8') }));
    });
    req.on('error', reject);
    req.end(payload);
  });
}

const results = [];
function chk(name, cond, detail) {
  results.push({ name, ok: !!cond, detail });
  console.log((cond ? 'PASS   ' : '>>FAIL ') + name + '  ' + (detail === undefined ? '' : detail));
}
function ol(s, n) { return String(s).slice(0, n || 90).replace(/\r?\n/g, '\\n'); }

