cat > src/lib/money.js <<'EOF'
'use strict';

// Currency amounts are numbers in the currency unit with at most two decimals
// (README.md "Rules"). This module owns every conversion between the currency
// unit and cents, and every decision about whether a value is representable;
// no other module may do that arithmetic.

function toCents(value) {
  return Math.round(value * 100);
}

// Returns null when `cents` cannot be carried as an exact currency amount,
// either because it is past the safe integer range or because dividing it
// does not round-trip. Callers must reject, never serve, a null.
function fromCents(cents) {
  if (!Number.isSafeInteger(cents)) return null;
  const value = cents / 100;
  return toCents(value) === cents ? value : null;
}

function isAmount(value) {
  return typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
    && Number.isSafeInteger(toCents(value))
    // Exact: `value` must be the nearest double to its own 2-decimal rounding.
    // A magnitude-relative epsilon admits 49.000000001 and rejects totals the
    // service itself computes, because double spacing passes 1e-6 near 1e8.
    && Number(value.toFixed(2)) === value;
}

function sumLineCents(items) {
  return items.reduce((cents, item) => cents + toCents(item.unitPrice) * item.quantity, 0);
}

function formatAmount(value) {
  return value.toFixed(2);
}

module.exports = { isAmount, toCents, fromCents, sumLineCents, formatAmount };
