'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs/promises');
const path = require('node:path');
const { notFound } = require('../lib/errors');
const { formatAmount } = require('../lib/money');

const CSV_HEADER = 'id,userId,status,total,createdAt';
// A report name is a name, never a path. Matching the shape this service
// generates is what keeps `name` out of path.join's traversal reach.
const REPORT_NAME = /^orders-[0-9]+-[0-9a-f]{6}\.csv$/;

function toCsvRow(order) {
  return [order.id, order.userId, order.status, formatAmount(order.total), order.createdAt].join(',');
}

function createReportService({ reportDir }) {
  async function exportOrders(orders) {
    await fs.mkdir(reportDir, { recursive: true });
    const name = `orders-${Date.now()}-${crypto.randomBytes(3).toString('hex')}.csv`;
    const rows = orders.map(toCsvRow);
    await fs.writeFile(path.join(reportDir, name), `${[CSV_HEADER, ...rows].join('\n')}\n`, 'utf8');
    return name;
  }

  async function read(name) {
    if (!REPORT_NAME.test(name)) throw notFound('report not found');
    try {
      return await fs.readFile(path.join(reportDir, name), 'utf8');
    } catch {
      throw notFound('report not found');
    }
  }

  return { exportOrders, read };
}

module.exports = { createReportService, CSV_HEADER };
EOF
