'use strict';
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createApp } = require('<run-project>/src/app.js');

function mk(port) {
  return (method, urlPath, { body, token } = {}) => new Promise((resolve, reject) => {
    const payload = body === undefined ? undefined : JSON.stringify(body);
    const headers = {};
    if (payload !== undefined) headers['content-type'] = 'application/json';
    if (token) headers.authorization = `Bearer ${token}`;
    const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        let parsed; try { parsed = JSON.parse(text); } catch {}
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    req.end(payload);
  });
}

(async () => {
  const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'dos-'));
  const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
  const app = createApp({ secret: 's', reportDir, admin: ADMIN });
  const port = await app.listen(0);
  const call = mk(port);
  await call('POST', '/users', { body: { email: 'alice@example.com', password: 'correct-horse', name: 'A' } });
  const token = (await call('POST', '/sessions', { body: { email: 'alice@example.com', password: 'correct-horse' } })).body.token;

  const time = async (fn) => { const t = process.hrtime.bigint(); await fn(); return Number(process.hrtime.bigint() - t) / 1e6; };

  const idle = await time(() => call('GET', '/users/me', { token }));

  // 20 concurrent unauthenticated logins, measuring an unrelated request mid-flight
  const logins = Array.from({ length: 20 }, () =>
    call('POST', '/sessions', { body: { email: 'alice@example.com', password: 'correct-horse' } }));
  await new Promise((r) => setTimeout(r, 5));
  const underLoad = await time(() => call('GET', '/users/me', { token }));
  const results = await Promise.all(logins);

  console.log('GET /users/me idle            :', idle.toFixed(1), 'ms');
  console.log('GET /users/me under 20 logins :', underLoad.toFixed(1), 'ms');
  console.log('all 20 logins succeeded       :', results.every((r) => r.status === 201));
  await app.close();
  fs.rmSync(reportDir, { recursive: true, force: true });
})();
EOF
