'use strict';

// Architecture rules as code, in the project's own stack: these are the
// dependency constraints the audit accepted, enforced without a third-party
// linter so the service keeps its zero-dependency promise.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const SRC = path.join(__dirname, '..', 'src');

// A subsystem is a directory, or a single file for a facade. Order matters:
// the first matching pattern owns the file.
const SUBSYSTEMS = [
  { name: 'root', match: (rel) => rel === 'app.js' },
  { name: 'transport', match: (rel) => rel.startsWith('http/') || rel.endsWith('/routes.js') },
  { name: 'service', match: (rel) => rel.endsWith('/service.js') },
  { name: 'persistence', match: (rel) => rel.startsWith('store/') },
  { name: 'shared', match: (rel) => rel.startsWith('lib/') },
  { name: 'auth', match: (rel) => rel.startsWith('auth/') },
];

const FORBIDDEN = [
  { from: 'transport', to: ['persistence'] },
  { from: 'shared', to: ['root', 'transport', 'service', 'persistence', 'auth'] },
];

// Durable storage is reachable without importing the persistence subsystem.
// A transport file that opens a file descriptor holds persistence concerns
// whatever its import list says.
const STORAGE_BUILTINS = ['node:fs', 'node:fs/promises', 'fs', 'fs/promises'];
const FORBIDDEN_BUILTINS = [{ from: 'transport', to: STORAGE_BUILTINS }];

function sourceFiles(dir = SRC, prefix = '') {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) return sourceFiles(path.join(dir, entry.name), rel);
    return entry.name.endsWith('.js') ? [rel] : [];
  });
}

function subsystemOf(rel) {
  const found = SUBSYSTEMS.find((subsystem) => subsystem.match(rel));
  return found ? found.name : null;
}

function read(rel) {
  return fs.readFileSync(path.join(SRC, rel), 'utf8');
}

// Both quote styles, and template literals: a rule a different quote character
// defeats is not a rule.
const REQUIRE_TARGET = /(?:require|import)\s*\(\s*['"`]([^'"`]+)['"`]\s*\)/g;

function requireTargets(rel) {
  return [...read(rel).matchAll(REQUIRE_TARGET)].map((match) => match[1]);
}

function internalImports(rel) {
  return requireTargets(rel)
    .filter((target) => target.startsWith('.'))
    .map((target) => {
      const resolved = path.relative(SRC, path.resolve(path.dirname(path.join(SRC, rel)), target));
      return `${resolved.split(path.sep).join('/').replace(/\.js$/, '')}.js`;
    });
}

// Strips block comments and whole comment lines, never code text: a rule that
// can be evaded is worse than one that occasionally over-reports.
function codeOf(rel) {
  return read(rel)
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .split('\n')
    .filter((line) => !/^\s*(\/\/|\*)/.test(line))
    .join('\n');
}

// Directive 8: a file matching no declared subsystem is invisible to every
// rule below, so an undeclared file is itself a failure.
test('every source file belongs to a declared subsystem', () => {
  const undeclared = sourceFiles().filter((rel) => subsystemOf(rel) === null);
  assert.deepEqual(undeclared, [], `undeclared files: ${undeclared.join(', ')}`);
});

// A rule that reads the working tree passes while the committed tree is
// broken: src/reports/ was invisible to git because .gitignore said
// "reports/" without anchoring it to the repository root.
test('every source file is tracked by git', () => {
  const tracked = new Set(
    execFileSync('git', ['ls-files', 'src/'], { cwd: path.join(__dirname, '..'), encoding: 'utf8' })
      .split('\n')
      .filter(Boolean)
      .map((line) => line.replace(/^src\//, '')),
  );
  const untracked = sourceFiles().filter((rel) => !tracked.has(rel));
  assert.deepEqual(untracked, [], `source files missing from git: ${untracked.join(', ')}`);
});

test('no subsystem imports across a forbidden edge', () => {
  const violations = [];
  for (const rel of sourceFiles()) {
    const from = subsystemOf(rel);
    const rule = FORBIDDEN.find((candidate) => candidate.from === from);
    if (!rule) continue;
    for (const target of internalImports(rel)) {
      const to = subsystemOf(target);
      if (rule.to.includes(to)) violations.push(`${rel} (${from}) -> ${target} (${to})`);
    }
  }
  assert.deepEqual(violations, [], `forbidden edges: ${violations.join('; ')}`);
});

test('no transport file reaches durable storage directly', () => {
  const violations = [];
  for (const rel of sourceFiles()) {
    const from = subsystemOf(rel);
    const rule = FORBIDDEN_BUILTINS.find((candidate) => candidate.from === from);
    if (!rule) continue;
    for (const target of requireTargets(rel)) {
      if (rule.to.includes(target)) violations.push(`${rel} (${from}) -> ${target}`);
    }
  }
  assert.deepEqual(violations, [], `forbidden storage access: ${violations.join('; ')}`);
});

// Aspect exclusivity: currency representation has one obligation and one
// mechanism. This constrains an operation rather than an import edge, so it
// is a coverage check, not a dependency rule.
test('only the money module converts or formats currency amounts', () => {
  const patterns = [/\*\s*100\b/, /\/\s*100\b/, /toFixed\s*\(/];
  const offenders = sourceFiles()
    .filter((rel) => rel !== 'lib/money.js')
    .filter((rel) => patterns.some((pattern) => pattern.test(codeOf(rel))));
  assert.deepEqual(offenders, [], `currency arithmetic outside lib/money.js: ${offenders.join(', ')}`);
});
EOF
