import pathlib
def append(path, text):
    p = pathlib.Path(path)
    s = p.read_text()
    with p.open('w', newline='\n') as fh:
        fh.write(s + text)

append('test/money.test.js', """
test('isAmount rejects values that are not exactly a two-decimal amount', () => {
  // A magnitude-blind tolerance admitted these: 49.000000001 was accepted as
  // payment for a total of 49, and 1e306 overflowed an order total to Infinity.
  for (const value of [49.000000001, 1.000000001, 1e306, 1e21, 8.285, 0.005]) {
    assert.equal(isAmount(value), false, `${value}`);
  }
});

test('isAmount accepts a large total the service itself can compute', () => {
  const large = fromCents(sumLineCents([{ unitPrice: 19.99, quantity: 6714245 }]));
  assert.equal(large, 134217757.55);
  // Rejecting this made such an order permanently unpayable and unshippable.
  assert.equal(isAmount(large), true);
});

test('fromCents refuses a total it cannot carry exactly', () => {
  assert.equal(fromCents(1e20), null);
  assert.equal(fromCents(3518447372878370), null);
  assert.equal(fromCents(Number.MAX_SAFE_INTEGER + 1), null);
  assert.equal(fromCents(13421775755), 134217757.55);
});

test('formatAmount renders two decimals', () => {
  assert.equal(formatAmount(24), '24.00');
  assert.equal(formatAmount(0.3), '0.30');
  assert.equal(formatAmount(134217757.55), '134217757.55');
});
""")

append('test/pagination.test.js', """
test('a pageSize the caller never wrote cannot win', () => {
  // Number.parseInt('1e3') is 1, so this used to return one item per page.
  assert.equal(paginate(items(500), { pageSize: '1e3' }).pageSize, 100);
  assert.equal(paginate(items(10), { page: '2.9' }).page, 1);
  assert.equal(paginate(items(10), { pageSize: '10abc' }).pageSize, 20);
});
""")

append('test/orders.test.js', """
test('an order whose total cannot be represented exactly is rejected', async (t) => {
  const { call, signUp } = await startApp(t);
  const token = await signUp('alice@example.com');
  const cases = [
    { items: [{ sku: 'HUGE-1', unitPrice: 1e306, quantity: 10 }] },
    { items: [{ sku: 'HUGE-2', unitPrice: 0.01, quantity: 1e20 }] },
    { items: [{ sku: 'HUGE-3', unitPrice: 0.01, quantity: 3518447372878370 }] },
  ];
  for (const body of cases) {
    const res = await call('POST', '/orders', { token, body });
    assert.equal(res.status, 400, JSON.stringify(body));
  }
  // Nothing partially created: the customer still has no orders.
  assert.equal((await call('GET', '/orders', { token })).body.total, 0);
});
""")

append('test/payments.test.js', """
test('an amount that is not exactly the total is rejected', async (t) => {
  const { call, signUp } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const order = await placeOrder(call, alice);
  // 49.000000001 collapsed to the same cents as 49 and was stored verbatim.
  for (const amount of [49.000000001, 48.999999999]) {
    const res = await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount } });
    assert.equal(res.status, 400, `${amount}`);
  }
  assert.equal((await call('GET', `/orders/${order.id}`, { token: alice })).body.status, 'pending');
});

test('a charge the gateway does not capture leaves the order unpaid', async (t) => {
  const declining = { charge: () => ({ id: 'dec_1', status: 'declined' }) };
  const { call, signUp } = await startApp(t, { paymentGateway: declining });
  const alice = await signUp('alice@example.com');
  const order = await placeOrder(call, alice);
  const res = await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: 49 } });
  assert.equal(res.status, 409);
  assert.equal((await call('GET', `/orders/${order.id}`, { token: alice })).body.status, 'pending');
});

test('an asynchronous gateway is awaited before the order is marked paid', async (t) => {
  const slow = {
